INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Cyber-physische Systeme nur in der Industrie 4.0 relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch in Medizin oder Verkehr genutzt"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgen diese Systeme?', 3, '[{"text": "Automatisierung erhöhen", "correct": true, "because": "Effizienz durch Vernetzung"}, {"text": "Hardware reparieren", "correct": false, "because": "Kein Fokus"}, {"text": "Daten löschen", "correct": false, "because": "Daten sind zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten gehören zu einem CPS?', 5, '[{"text": "Sensoren", "correct": true, "because": "Erfassen Daten"}, {"text": "Aktoren", "correct": true, "because": "Beeinflussen physische Welt"}, {"text": "Grafikkarten", "correct": false, "because": "Nicht essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) CPS verbinden physische und digitale Welt. b) Sie arbeiten offline.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Netzwerk ist nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Planung eines CPS?', 4, '[{"text": "Sicherheit", "correct": false, "because": "Schutz ist kritisch"}, {"text": "Vernetzung", "correct": false, "because": "Kern der Funktion"}, {"text": "Bürodekor", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob CPS immer autonom sind?', 2, '[{"text": "Nein", "correct": true, "because": "Können auch gesteuert werden"}, {"text": "Ja", "correct": false, "because": "Flexibel einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologie ist für CPS zentral?', 3, '[{"text": "Internet der Dinge", "correct": true, "because": "Ermöglicht Vernetzung"}, {"text": "USB", "correct": false, "because": "Kein Netzwerkfokus"}, {"text": "Bluetooth", "correct": false, "because": "Nur eine Option"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten CPS?', 5, '[{"text": "Effizienzsteigerung", "correct": true, "because": "Automatisierung spart Zeit"}, {"text": "Echtzeitsteuerung", "correct": true, "because": "Schnelle Reaktion"}, {"text": "Geringere Kosten", "correct": false, "because": "Nicht immer"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) CPS sind komplex. b) Sie brauchen keinen Strom. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Strom ist nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein CPS?', 4, '[{"text": "Netzwerk", "correct": false, "because": "Kern der Kommunikation"}, {"text": "Software", "correct": false, "because": "Steuerung nötig"}, {"text": "Kaffeemaschine", "correct": true, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind CPS dasselbe wie IoT?', 2, '[{"text": "Nein", "correct": true, "because": "CPS umfassen physische Steuerung"}, {"text": "Ja", "correct": false, "because": "IoT ist Teil davon"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bereiche nutzen CPS?', 4, '[{"text": "Produktion", "correct": true, "because": "Smart Factory"}, {"text": "Medizin", "correct": true, "because": "Echtzeitüberwachung"}, {"text": "Gaming", "correct": false, "because": "Weniger relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass CPS keine Sensoren brauchen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Sensoren erfassen Daten"}, {"text": "Ja", "correct": false, "because": "Sensoren sind essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem CPS?', 3, '[{"text": "Sicherheitskonzepte", "correct": true, "because": "Schutz vor Angriffen"}, {"text": "Schnelle Hardware", "correct": false, "because": "Sekundär"}, {"text": "Geringer Preis", "correct": false, "because": "Qualität zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) CPS nutzen Echtzeitdaten. b) Sie sind wartungsfrei.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Wartung nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen gibt es bei CPS?', 5, '[{"text": "Komplexität", "correct": true, "because": "Viele Komponenten"}, {"text": "Sicherheitsrisiken", "correct": true, "because": "Angriffsfläche"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Hauptthema"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei CPS unwichtig?', 3, '[{"text": "Datenverarbeitung", "correct": false, "because": "Kernfunktion"}, {"text": "Vernetzung", "correct": false, "because": "Essenziell"}, {"text": "Monitorgröße", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Arbeiten CPS ohne Aktoren?', 3, '[{"text": "Nein", "correct": true, "because": "Aktoren steuern physisch"}, {"text": "Ja", "correct": false, "because": "Aktoren sind nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob CPS nur lokal arbeiten?', 2, '[{"text": "Nein", "correct": true, "because": "Auch global vernetzt"}, {"text": "Ja", "correct": false, "because": "Internetfähig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature macht CPS besonders?', 4, '[{"text": "Integration", "correct": true, "because": "Physisch und digital verbunden"}, {"text": "Hohe Lautstärke", "correct": false, "because": "Irrelevant"}, {"text": "Kleine Größe", "correct": false, "because": "Nicht entscheidend"}]');
